// Сделки с причиной отказа «Дубль» не анализируем совсем (решение Сани 06.10.2026).
//
// Дубль — техническая сделка: общение идёт в основной, а в дубле его обычно нет. За всё время
// таких сделок 49, по ним прошло 52 разбора, 304 минуты работы конвейера и 1 012 855 входных
// токенов. В 33 случаях из 52 судья отвечал «недостаточно данных» — то есть деньги тратились
// на заведомо пустой разбор.
//
// Что делаем: сделку пропускаем до транскрипции и анализа. Карточку в `lost_deals` пишем как
// обычно, чтобы было видно, что сделка была. В `lost_deal_analyses` не пишем ничего — значит
// такая сделка не попадёт ни в `lost_pipeline_attention`, ни в ночной повтор.
//
// Как сравнивать. В сделке Битрикс хранит ИДЕНТИФИКАТОР значения списка
// (`UF_CRM_1584703948317`), а текст подставляется из справочника `crm.deal.userfield.list`.
// Поэтому основной признак — идентификатор: он переживёт переименование значения в Битриксе.
// Текст оставлен запасным: он сработает, если значение пересоздадут с новым идентификатором.
// Срабатывает любой из двух признаков.
//
// Источник правок — этот файл. Моки: tests/duplicate-skip/run.js

// Идентификатор значения «Дубль» в справочнике причин отказа (проверено 06.10.2026,
// поле UF_CRM_1584703948317, тип enumeration, 22 значения).
var DUPLICATE_REASON_ID = '3297';

// Запасной признак — текст причины, без учёта регистра и пробелов по краям.
var DUPLICATE_REASON_TEXT = 'дубль';

function isDuplicateReason(reasonId, reasonText) {
  if (reasonId !== null && reasonId !== undefined && String(reasonId).trim() === DUPLICATE_REASON_ID) {
    return true;
  }
  var t = String(reasonText === null || reasonText === undefined ? '' : reasonText).trim().toLowerCase();
  return t === DUPLICATE_REASON_TEXT;
}
